import{_ as e,c as t,o as n,a2 as o}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1780466351000}'),i={name:"guide/introduction.md"};function r(s,a,l,u,d,p){return n(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="about-gomoku" tabindex="-1">About Gomoku <a class="header-anchor" href="#about-gomoku" aria-label="Permalink to &quot;About Gomoku&quot;">​</a></h2><p>Gomoku is a classic five-in-a-row board game. This site provides documentation, guides, and tools for the Gomoku project including rules, game play, analysis, and deployment of web or native clients.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="🎯-play-learn-gomoku" tabindex="-1">🎯 <strong>Play &amp; Learn Gomoku</strong> <a class="header-anchor" href="#🎯-play-learn-gomoku" aria-label="Permalink to &quot;🎯 **Play &amp; Learn Gomoku**&quot;">​</a></h3><p>Quickly start games, learn rules, and practice with analysis tools.</p><h3 id="🤖-analysis-ai-opponent" tabindex="-1">🤖 <strong>Analysis &amp; AI Opponent</strong> <a class="header-anchor" href="#🤖-analysis-ai-opponent" aria-label="Permalink to &quot;🤖 **Analysis &amp; AI Opponent**&quot;">​</a></h3><p>Play against an AI opponent, analyze positions, and review games with built-in tools.</p><h3 id="📚-guides-tutorials" tabindex="-1">📚 <strong>Guides &amp; Tutorials</strong> <a class="header-anchor" href="#📚-guides-tutorials" aria-label="Permalink to &quot;📚 **Guides &amp; Tutorials**&quot;">​</a></h3><p>Step-by-step guides for beginners and advanced players: rules, strategies, and annotated games.</p><h3 id="🌐-web-extension-integration" tabindex="-1">🌐 <strong>Web &amp; Extension Integration</strong> <a class="header-anchor" href="#🌐-web-extension-integration" aria-label="Permalink to &quot;🌐 **Web &amp; Extension Integration**&quot;">​</a></h3><p>Information about web clients, integrations, and optional browser extensions (if applicable).</p><h3 id="🌐-browser-integration-optional" tabindex="-1">🌐 <strong>Browser Integration (Optional)</strong> <a class="header-anchor" href="#🌐-browser-integration-optional" aria-label="Permalink to &quot;🌐 **Browser Integration (Optional)**&quot;">​</a></h3><p>If a browser extension or web client exists for Gomoku, it will be documented here. Browser integrations are optional and not required for core gameplay.</p><h3 id="🎨-clean-interface" tabindex="-1">🎨 <strong>Clean Interface</strong> <a class="header-anchor" href="#🎨-clean-interface" aria-label="Permalink to &quot;🎨 **Clean Interface**&quot;">​</a></h3><p>A minimal and focused interface to keep the attention on the board and the game.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>Operating System</strong>: macOS 10.13 or later</li><li><strong>Memory</strong>: 4GB RAM minimum, 8GB recommended</li><li><strong>Storage</strong>: 54.5 MB for installation</li><li><strong>Display</strong>: 1280x720 minimum resolution</li></ul><h2 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported Languages&quot;">​</a></h2><p>Gomoku supports a wide range of languages, including English, Chinese (Simplified), Chinese (Traditional), Japanese, French, Korean, German, Spanish, Italian, Vietnamese, Thai, Hindi, Turkish, Russian, Portuguese, Dutch, Finnish, Malay, Greek, Norwegian, Indonesian, Hungarian, Danish, and Ukrainian.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>If you&#39;re new to Gomoku, start with the <a href="/guide/installation.html">Installation Guide</a> to get the application running on your Mac.</p>',22)])])}const m=e(i,[["render",r]]);export{g as __pageData,m as default};
